#ifndef PKCS7_INT_H
#define PKCS7_INT_H

#include <gnutls/x509.h>

/* PKCS #7
 */
#define DATA_OID "1.2.840.113549.1.7.1"
#define ENC_DATA_OID "1.2.840.113549.1.7.6"

#define SIGNED_DATA_OID "1.2.840.113549.1.7.2"
#define DIGESTED_DATA_OID "1.2.840.113549.1.7.5"


typedef enum schema_id {
        PBES2_GENERIC=1,        /* when the algorithm is unknown, temporal use when reading only */
        PBES2_DES,              /* the stuff in PKCS #5 */
        PBES2_3DES,
        PBES2_AES_128,
        PBES2_AES_192,
        PBES2_AES_256,
        PBES2_GOST28147_89_TC26Z,
        PBES2_GOST28147_89_CPA,
        PBES2_GOST28147_89_CPB,
        PBES2_GOST28147_89_CPC,
        PBES2_GOST28147_89_CPD,
        PKCS12_3DES_SHA1,       /* the stuff in PKCS #12 */
        PKCS12_ARCFOUR_SHA1,
        PKCS12_RC2_40_SHA1,
        PBES1_DES_MD5           /* openssl before 1.1.0 uses that by default */
} schema_id;

struct pkcs_cipher_schema_st {
        unsigned int schema;
        const char *name;
        unsigned int flag;
        unsigned int cipher;
        unsigned pbes2;
        const char *cipher_oid;
        const char *write_oid;
        const char *desc;
        const char *iv_name;
        unsigned decrypt_only;
};

const struct pkcs_cipher_schema_st *_gnutls_pkcs_schema_get(schema_id schema);

struct pbe_enc_params {
        gnutls_cipher_algorithm_t cipher;
        uint8_t iv[MAX_CIPHER_BLOCK_SIZE];
        int iv_size;
        char pbes2_oid[MAX_OID_SIZE]; /* when reading params, the OID is stored for info purposes */
};

int
_gnutls_decrypt_pbes1_des_md5_data(const char *password,
                           unsigned password_len,
                           const struct pbkdf2_params *kdf_params,
                           const struct pbe_enc_params *enc_params,
                           gnutls_datum_t *encrypted_data, /* overwritten */
                           gnutls_datum_t *decrypted_data);

int _gnutls_check_pkcs_cipher_schema(const char *oid);

int
_gnutls_pkcs_raw_decrypt_data(schema_id schema, ASN1_TYPE pkcs8_asn,
             const char *root, const char *password,
             const struct pbkdf2_params *kdf_params,
             const struct pbe_enc_params *enc_params,
             gnutls_datum_t *decrypted_data);

int
_gnutls_pkcs_raw_encrypt_data(const gnutls_datum_t * plain,
             const struct pbe_enc_params *enc_params,
             gnutls_datum_t * key, gnutls_datum_t * encrypted);

int _gnutls_pkcs7_decrypt_data(const gnutls_datum_t * data,
                               const char *password, gnutls_datum_t * dec);

int _gnutls_read_pbkdf1_params(const uint8_t * data, int data_size,
                       struct pbkdf2_params *kdf_params,
                       struct pbe_enc_params *enc_params);

int
_gnutls_read_pkcs_schema_params(schema_id * schema, const char *password,
                        const uint8_t * data, int data_size,
                        struct pbkdf2_params *kdf_params,
                        struct pbe_enc_params *enc_params);

int
_gnutls_pkcs_write_schema_params(schema_id schema, ASN1_TYPE pkcs8_asn,
                    const char *where,
                    const struct pbkdf2_params *kdf_params,
                    const struct pbe_enc_params *enc_params);

int
_gnutls_pkcs_generate_key(schema_id schema,
             const char *password,
             struct pbkdf2_params *kdf_params,
             struct pbe_enc_params *enc_params, gnutls_datum_t * key);

int _gnutls_pkcs_flags_to_schema(unsigned int flags);
int _gnutls_pkcs7_encrypt_data(schema_id schema,
                               const gnutls_datum_t * data,
                               const char *password, gnutls_datum_t * enc);

int
_gnutls_pkcs7_data_enc_info(const gnutls_datum_t * data, const struct pkcs_cipher_schema_st **p,
        struct pbkdf2_params *kdf_params, char **oid);

#endif

---BUILD---

export DEPS_PATH=$SRC/deps
export PKG_CONFIG_PATH=$DEPS_PATH/lib/pkgconfig
export CPPFLAGS="-I$DEPS_PATH/include"
export LDFLAGS="-L$DEPS_PATH/lib"
export GNULIB_SRCDIR=$SRC/gnulib
cd $SRC/libunistring
./autogen.sh
ASAN_OPTIONS=detect_leaks=0   ./configure --enable-static --disable-shared --prefix=$DEPS_PATH
make -j$(nproc)
make install
cd $SRC/libidn2
./bootstrap
ASAN_OPTIONS=detect_leaks=0   ./configure --enable-static --disable-shared --disable-doc --disable-gcc-warnings --prefix=$DEPS_PATH
make -j$(nproc)
make install
GMP_CONFIGURE_FLAGS="--disable-assembly --disable-fat"
cd $SRC/gmp
bash .bootstrap
ASAN_OPTIONS=detect_leaks=0   ./configure --disable-shared --prefix=$DEPS_PATH $GMP_CONFIGURE_FLAGS
make -j$(nproc)
make install
cd $SRC/libtasn1
CFGFLAGS="--disable-gcc-warnings --disable-gtk-doc --disable-gtk-doc-pdf --disable-doc   --disable-shared --enable-static --prefix=$DEPS_PATH"   make bootstrap
make -j$(nproc)
make install
NETTLE_CONFIGURE_FLAGS=""
if [[ $CFLAGS = *sanitize=memory* ]]; then
  NETTLE_CONFIGURE_FLAGS="--disable-assembler --disable-fat"
fi
cd $SRC/nettle
bash .bootstrap
ASAN_OPTIONS=detect_leaks=0   ./configure --enable-static --disable-shared --disable-documentation --prefix=$DEPS_PATH $NETTLE_CONFIGURE_FLAGS
( make -j$(nproc) || make -j$(nproc) ) && make install
if test $? != 0; then
  echo "Failed to compile nettle"
  exit 1
fi
GNUTLS_CONFIGURE_FLAGS=""
if [[ $CFLAGS = *sanitize=memory* ]]; then
  GNUTLS_CONFIGURE_FLAGS="--disable-hardware-acceleration"
fi
cd $SRC/gnutls
make autoreconf
ASAN_OPTIONS=detect_leaks=0 LIBS="-lunistring" CXXFLAGS="$CXXFLAGS -L$DEPS_PATH/lib"   ./configure --enable-fuzzer-target --disable-gcc-warnings --enable-static --disable-shared --disable-doc --disable-tests     --disable-tools --disable-cxx --disable-maintainer-mode --disable-libdane --without-p11-kit $GNUTLS_CONFIGURE_FLAGS
sed -i 's|include <sys/syscall.h>|include <sys/syscall.h>\n#undef SYS_getrandom|' lib/nettle/sysrng-linux.c
make -j$(nproc) -C gl
make -j$(nproc) -C lib
cd fuzz
make oss-fuzz
find . -name '*_fuzzer' -exec cp -v '{}' $OUT ';'
find . -name '*_fuzzer.dict' -exec cp -v '{}' $OUT ';'
find . -name '*_fuzzer.options' -exec cp -v '{}' $OUT ';'
for dir in *_fuzzer.in; do
    fuzzer=$(basename $dir .in)
    zip -rj "$OUT/${fuzzer}_seed_corpus.zip" "${dir}/"
done
